"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6107],{13229:e=>{e.exports=JSON.parse('{"functions":[{"name":"setupHotReload","desc":"Registers every system module in the given containers and keeps watching them\\nfor edits.\\n\\nModules are tracked by their *original* module rather than the reloaded copy,\\nwhich is what lets an edited system replace its running self instead of\\nstacking a second copy alongside it. A module that fails to load is warned\\nabout and skipped, so one broken system does not take the whole scheduler\\ndown mid-session.","params":[{"name":"containers","desc":"Folders of system modules.","lua_type":"{ { ModuleScript } }"}],"returns":[],"function_type":"static","private":true,"source":{"line":34,"path":"src/main/shared/startup.luau"}},{"name":"loadModule","desc":"Registers a system module, replacing its previous incarnation if this is a\\nreload rather than a first load.\\n\\n\\t","params":[{"name":"module","desc":"The (possibly reloaded) module.","lua_type":"ModuleScript"},{"name":"context","desc":"Rewire context; carries the original module identity.","lua_type":"table"}],"returns":[],"function_type":"static","private":true,"source":{"line":46,"path":"src/main/shared/startup.luau"}},{"name":"unloadModule","desc":"Removes a system from the scheduler when its module goes away for good.\\n\\nDoes nothing mid-reload: `loadModule` is about to swap the system in\\nplace, and removing it first would drop it from the schedule entirely.\\n\\n\\t","params":[{"name":"_module","desc":"Unused.","lua_type":"ModuleScript"},{"name":"context","desc":"Rewire context; `isReloading` distinguishes the two cases.","lua_type":"table"}],"returns":[],"function_type":"static","private":true,"source":{"line":76,"path":"src/main/shared/startup.luau"}},{"name":"startup","desc":"Starts the ECS for this side of the game.\\n\\nOn the client this also binds F4 to open the Jabby inspector.","params":[{"name":"containers","desc":"Folders of system modules.","lua_type":"{ { ModuleScript } } | Folder"}],"returns":[],"function_type":"static","source":{"line":104,"path":"src/main/shared/startup.luau"}},{"name":"createWidget","desc":"Opens the Jabby inspector on key down.\\n\\n\\t\\t","params":[{"name":"_name","desc":"Unused action name.","lua_type":"string"},{"name":"state","desc":"Only `Begin` opens the widget.","lua_type":"Enum.UserInputState"}],"returns":[],"function_type":"static","private":true,"source":{"line":118,"path":"src/main/shared/startup.luau"}}],"properties":[],"types":[],"name":"startup","desc":"Boots the ECS: registers every system module with the scheduler, keeps them\\nhot-reloadable, and exposes the world to Jabby.","tags":["core"],"source":{"line":9,"path":"src/main/shared/startup.luau"}}')}}]);